const CardId* sts2CombatGenPool(const char* pool, int* count) {
    if (!pool) return nullptr;
    for (const auto& e : kPools) {
        if (std::strcmp(e.pool, pool) == 0) {
            if (count) *count = e.count;
            return e.cards;
        }
    }
    if (count) *count = 0;
    return nullptr;
}

